from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel


class Item(BaseModel):
    name: str
    description: str | None = None
    price: float | None = None


def get_item() -> Item:
    return Item(name="Foo")


def test_app_default_true_excludes_none():
    app = FastAPI(default_response_model_exclude_none=True)
    app.get("/item", response_model=Item)(get_item)

    response = TestClient(app).get("/item")
    assert response.status_code == 200, response.text
    assert response.json() == {"name": "Foo"}


def test_app_default_false_includes_none():
    app = FastAPI()
    assert app.default_response_model_exclude_none is False
    app.get("/item", response_model=Item)(get_item)

    response = TestClient(app).get("/item")
    assert response.status_code == 200, response.text
    assert response.json() == {"name": "Foo", "description": None, "price": None}


def test_explicit_route_value_overrides_app_default():
    app = FastAPI(default_response_model_exclude_none=True)
    app.get("/item", response_model=Item)(get_item)
    app.get("/item-with-none", response_model=Item, response_model_exclude_none=False)(
        get_item
    )

    client = TestClient(app)
    response = client.get("/item")
    assert response.status_code == 200, response.text
    assert response.json() == {"name": "Foo"}

    response = client.get("/item-with-none")
    assert response.status_code == 200, response.text
    assert response.json() == {"name": "Foo", "description": None, "price": None}

